import { createHash, randomBytes } from "node:crypto";
import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
import path from "node:path";
import sharp from "sharp";
import { fetchBounded, type MetadataFetcherOptions } from "./fetcher.js";

const ICON_LIMIT = 256 * 1024;
const TOKEN_TTL_MS = 15 * 60_000;
const tokens = new Map<string, { asset: string; expiresAt: number }>();

export async function retrieveIcon(url: string, options?: MetadataFetcherOptions, iconDir = path.join(process.cwd(), "data/icons")): Promise<string | null> {
  try {
    const fetched = await fetchBounded(url, { ...options, limits: { ...options?.limits, maxCompressedBytes: ICON_LIMIT, maxDecompressedBytes: ICON_LIMIT } }, "icon");
    if (fetched.contentType.includes("svg") || fetched.body.length > ICON_LIMIT) return null;
    const metadata = await sharp(fetched.body, { failOn: "error", limitInputPixels: 16_777_216 }).metadata();
    if (!["png", "jpeg", "gif", "webp", "ico"].includes(metadata.format ?? "")) return null;
    const png = await sharp(fetched.body, { failOn: "error" }).resize(64, 64, { fit: "contain", withoutEnlargement: true }).png({ compressionLevel: 9 }).toBuffer();
    const asset = `${createHash("sha256").update(png).digest("hex")}.png`;
    await mkdir(iconDir, { recursive: true });
    const temporary = path.join(iconDir, `.${asset}.${randomBytes(6).toString("hex")}.tmp`);
    await writeFile(temporary, png, { flag: "wx" });
    await rename(temporary, path.join(iconDir, asset)).catch(async (error: NodeJS.ErrnoException) => {
      if (error.code !== "EEXIST") throw error;
    });
    const token = randomBytes(24).toString("base64url");
    tokens.set(token, { asset, expiresAt: Date.now() + TOKEN_TTL_MS });
    return token;
  } catch { return null; }
}

export function redeemIconToken(token: string): string | null {
  if (!/^[A-Za-z0-9_-]{32}$/u.test(token)) return null;
  const entry = tokens.get(token);
  if (!entry || entry.expiresAt < Date.now()) { tokens.delete(token); return null; }
  return entry.asset;
}

export async function readIconAsset(asset: string, iconDir = path.join(process.cwd(), "data/icons")): Promise<Buffer | null> {
  if (!/^[a-f0-9]{64}\.png$/u.test(asset)) return null;
  try { return await readFile(path.join(iconDir, asset)); } catch { return null; }
}

lib/metadata/fetcher.ts
import { gunzipSync, inflateSync, brotliDecompressSync } from "node:zlib";
import { request, type Dispatcher } from "undici";
import { createPinnedDispatcher, resolvePublicTarget, sanitizeMetadataError, validateMetadataUrl, type Resolver } from "./network-policy.js";

export interface FetchLimits { maxCompressedBytes: number; maxDecompressedBytes: number; timeoutMs: number; maxRedirects: number }
export interface FetchResult { finalUrl: string; contentType: string; body: Buffer }
export interface MetadataFetcherOptions {
  resolver?: Resolver;
  limits?: Partial<FetchLimits>;
  dispatcherFactory?: (url: URL, target: Awaited<ReturnType<typeof resolvePublicTarget>>) => Dispatcher;
}

const DEFAULT_LIMITS: FetchLimits = { maxCompressedBytes: 512 * 1024, maxDecompressedBytes: 2 * 1024 * 1024, timeoutMs: 10_000, maxRedirects: 5 };
let active = 0;
const MAX_CONCURRENT = 8;

async function collect(body: AsyncIterable<Uint8Array>, max: number): Promise<Buffer> {
  const chunks: Buffer[] = [];
  let length = 0;
  for await (const chunk of body) {
    length += chunk.byteLength;
    if (length > max) throw new Error("limit");
    chunks.push(Buffer.from(chunk));
  }
  return Buffer.concat(chunks);
}

function decode(body: Buffer, encoding: string | undefined, max: number): Buffer {
  let result: Buffer;
  if (!encoding || encoding === "identity") result = body;
  else if (encoding === "gzip" || encoding === "x-gzip") result = gunzipSync(body, { maxOutputLength: max });
  else if (encoding === "deflate") result = inflateSync(body, { maxOutputLength: max });
  else if (encoding === "br") result = brotliDecompressSync(body, { maxOutputLength: max });
  else throw new Error("encoding");
  if (result.length > max) throw new Error("limit");
  return result;
}

export async function fetchBounded(urlInput: string | URL, options: MetadataFetcherOptions = {}, kind: "html" | "icon" = "html"): Promise<FetchResult> {
  if (active >= MAX_CONCURRENT) throw sanitizeMetadataError(null);
  active++;
  const limits = { ...DEFAULT_LIMITS, ...options.limits };
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), limits.timeoutMs);
  let dispatcher: Dispatcher | undefined;
  let ownsDispatcher = false;
  try {
    let url = validateMetadataUrl(urlInput);
    for (let redirect = 0; ; redirect++) {
      const target = await resolvePublicTarget(url, options.resolver);
      dispatcher = options.dispatcherFactory?.(url, target) ?? createPinnedDispatcher(url, target);
      ownsDispatcher = !options.dispatcherFactory;
      const response = await request(url, {
        dispatcher, signal: controller.signal,
        headers: { accept: kind === "html" ? "text/html,application/xhtml+xml" : "image/png,image/jpeg,image/gif,image/webp,image/x-icon", "user-agent": "BookmarkManagerMetadata/1.0" },
        headersTimeout: limits.timeoutMs, bodyTimeout: limits.timeoutMs,
      });
      if ([301, 302, 303, 307, 308].includes(response.statusCode)) {
        await response.body.dump();
        if (redirect >= limits.maxRedirects) throw new Error("redirect");
        const location = response.headers.location;
        if (!location) throw new Error("redirect");
        url = validateMetadataUrl(new URL(Array.isArray(location) ? location[0]! : location, url));
        if (ownsDispatcher) await dispatcher.close();
        dispatcher = undefined;
        continue;
      }
      if (response.statusCode < 200 || response.statusCode >= 300) throw new Error("status");
      const contentType = String(response.headers["content-type"] ?? "").split(";", 1)[0]!.trim().toLowerCase();
      if (kind === "html" && contentType !== "text/html" && contentType !== "application/xhtml+xml") throw new Error("content-type");
      const compressed = await collect(response.body, limits.maxCompressedBytes);
      const body = decode(compressed, String(response.headers["content-encoding"] ?? "").toLowerCase(), limits.maxDecompressedBytes);
      return { finalUrl: url.href, contentType, body };
    }
  } catch (error) {
    throw sanitizeMetadataError(error);
  } finally {
    clearTimeout(timer); active--;
    if (dispatcher && ownsDispatcher) await dispatcher.close().catch(() => undefined);
  }
}

export function fetchHtml(url: string | URL, options?: MetadataFetcherOptions): Promise<FetchResult> {
  return fetchBounded(url, options, "html");
}
lib/metadata/service.ts
import { fallbackTitle, parseDocumentMetadata } from "./html.js";
import { fetchHtml, type MetadataFetcherOptions } from "./fetcher.js";
import { retrieveIcon } from "./icons.js";

export type TitleOrigin = "fetched" | "fallback" | "user";
export interface MetadataPreview { normalizedUrl: string; title: string; titleOrigin: "fetched" | "fallback"; iconToken: string | null; warning: string | null; existingBookmarkId: string | null }
export interface PreviewDependencies {
  normalizeUrl: (url: string) => string | { url?: string; normalizedUrl?: string };
  findExistingId?: (normalizedUrl: string) => Promise<string | null>;
  fetchOptions?: MetadataFetcherOptions;
  fetchPage?: typeof fetchHtml;
  fetchIcon?: typeof retrieveIcon;
}

export function titleOriginAfterEdit(previous: TitleOrigin, oldTitle: string, newTitle: string): TitleOrigin {
  return oldTitle.trim() === newTitle.trim() ? previous : "user";
}

export async function createMetadataPreview(input: string, dependencies: PreviewDependencies): Promise<MetadataPreview> {
  const normalized = dependencies.normalizeUrl(input);
  const normalizedUrl = typeof normalized === "string" ? normalized : normalized.normalizedUrl ?? normalized.url;
  if (!normalizedUrl) throw new Error("URL normalization returned no URL");
  const existingBookmarkId = await dependencies.findExistingId?.(normalizedUrl) ?? null;
  try {
    const page = await (dependencies.fetchPage ?? fetchHtml)(normalizedUrl, dependencies.fetchOptions);
    const metadata = parseDocumentMetadata(page.body.toString("utf8"), page.finalUrl);
    if (!metadata.title) throw new Error("missing title");
    let iconToken: string | null = null;
    for (const candidate of metadata.iconCandidates) {
      iconToken = await (dependencies.fetchIcon ?? retrieveIcon)(candidate.url, dependencies.fetchOptions);
      if (iconToken) break;
    }
    return { normalizedUrl, title: metadata.title, titleOrigin: "fetched", iconToken, warning: null, existingBookmarkId };
  } catch {
    return { normalizedUrl, title: fallbackTitle(normalizedUrl), titleOrigin: "fallback", iconToken: null, warning: "We could not retrieve this page’s details. You can edit the title and save it anyway.", existingBookmarkId };
  }
}

